// C# port of src/pbrt/wavefront/workitems.h, workitems.soa and workqueue.h
//
// pbrt stores the work items as structures of arrays (generated by soac
// from workitems.soa) so that GPU threads access memory coherently; here a
// WorkQueue is an array of work-item structs, and PixelSampleState is a
// class with an array per member. pbrt's MultiWorkQueues have a queue per
// concrete material or phase function type; here MaterialEvalWorkItem and
// MediumScatterWorkItem hold a Material or PhaseFunction reference (virtual
// dispatch selects the implementation), so a single queue holds them all.
// The order of the items in a queue depends on thread timing, as in pbrt,
// but each path is processed independently, so the image doesn't.

namespace Pbrt;

// RaySamples Definition
public struct RaySamples
{
    // RaySamples Public Members
    public struct DirectSamples
    {
        public Point2f u;
        public Float uc;
    }

    public struct IndirectSamples
    {
        public Float uc, rr;
        public Point2f u;
    }

    public struct SubsurfaceSamples
    {
        public Float uc;
        public Point2f u;
    }

    public DirectSamples direct;
    public IndirectSamples indirect;
    public bool haveSubsurface;
    public SubsurfaceSamples subsurface;
}

// PixelSampleState Definition
public sealed class PixelSampleState(int n)
{
    // PixelSampleState Public Members
    public readonly Float[] filterWeight = new Float[n];
    public readonly Point2i[] pPixel = new Point2i[n];
    public readonly SampledWavelengths[] lambda = new SampledWavelengths[n];
    public readonly SampledSpectrum[] L = new SampledSpectrum[n];
    public readonly SampledSpectrum[] cameraRayWeight = new SampledSpectrum[n];
    public readonly VisibleSurface[] visibleSurface = new VisibleSurface[n];
    public readonly RaySamples[] samples = new RaySamples[n];
}

