// MaterialEvalWorkItem Definition
public struct MaterialEvalWorkItem
{
    // MaterialEvalWorkItem Public Methods
    public readonly NormalBumpEvalContext GetNormalBumpEvalContext(Float dudx, Float dudy, Float dvdx, Float dvdy)
    {
        NormalBumpEvalContext ctx = new()
        {
            p = new Point3f(pi),
            uv = uv,
            dudx = dudx,
            dudy = dudy,
            dvdx = dvdx,
            dvdy = dvdy,
            faceIndex = faceIndex
        };
        ctx.shading.n = ns;
        ctx.shading.dpdu = dpdus;
        ctx.shading.dpdv = dpdvs;
        ctx.shading.dndu = dndus;
        ctx.shading.dndv = dndvs;
        return ctx;
    }

    public readonly MaterialEvalContext GetMaterialEvalContext(Float dudx, Float dudy, Float dvdx, Float dvdy,
                                                               Normal3f ns, Vector3f dpdus) =>
        new()
        {
            tex = new TextureEvalContext(new Point3f(pi), new Vector3f(), new Vector3f(), n, uv, dudx, dudy, dvdx,
                                         dvdy, faceIndex),
            wo = wo,
            ns = ns,
            dpdus = dpdus
        };

    // MaterialEvalWorkItem Public Members
    public Material material;
    public Point3fi pi;
    public Normal3f n;
    public Vector3f dpdu, dpdv;
    public Float time;
    public int depth;
    public Normal3f ns;
    public Vector3f dpdus, dpdvs;
    public Normal3f dndus, dndvs;
    public Point2f uv;
    public int faceIndex;
    public SampledWavelengths lambda;
    public int pixelIndex;
    public bool anyNonSpecularBounces;
    public Vector3f wo;
    public SampledSpectrum beta, r_u;
    public Float etaScale;
    public MediumInterface mediumInterface;
}

// WorkQueue Definition
public class WorkQueue<WorkItem>(int n) where WorkItem : struct
{
    // WorkQueue Private Members
    private readonly WorkItem[] items = new WorkItem[n];
    private int size = 0;

    // WorkQueue Public Methods
    public int Size() => Volatile.Read(ref size);

    public void Reset() => Volatile.Write(ref size, 0);

    public int Push(in WorkItem w)
    {
        int index = AllocateEntry();
        items[index] = w;
        return index;
    }

    public ref WorkItem this[int index] => ref items[index];

    // WorkQueue Protected Methods
    protected int AllocateEntry() => Interlocked.Increment(ref size) - 1;
}

public delegate void WorkItemFunc<WorkItem>(in WorkItem w) where WorkItem : struct;

public static partial class Util
{
    // WorkQueue Inline Functions
    // (pbrt's description string names the GPU kernel.)
    public static void ForAllQueued<WorkItem>(WorkQueue<WorkItem> q, WorkItemFunc<WorkItem> func)
        where WorkItem : struct =>
        // Process _q_ using _func_ with CPU threads
        ParallelFor(0, q.Size(), (long index) => func(in q[(int)index]));
}

// RayQueue Definition
public sealed class RayQueue(int n) : WorkQueue<RayWorkItem>(n)
{
    // RayQueue Public Methods
    public int PushCameraRay(in Ray ray, in SampledWavelengths lambda, int pixelIndex)
    {
        int index = AllocateEntry();
        DCHECK(!ray.HasNaN());
        ref RayWorkItem w = ref this[index];
        w.ray = ray;
        w.depth = 0;
        w.pixelIndex = pixelIndex;
        w.lambda = lambda;
        w.beta = new SampledSpectrum(1f);
        w.etaScale = 1f;
        w.anyNonSpecularBounces = false;
        w.r_u = new SampledSpectrum(1f);
        w.r_l = new SampledSpectrum(1f);
        w.specularBounce = false;
        // (pbrt leaves prevIntrCtx as it was; it's only used at depth > 0.)
        w.prevIntrCtx = new LightSampleContext();
        return index;
    }

    public int PushIndirectRay(in Ray ray, int depth, in LightSampleContext prevIntrCtx, in SampledSpectrum beta,
                               in SampledSpectrum r_u, in SampledSpectrum r_l, in SampledWavelengths lambda,
                               Float etaScale, bool specularBounce, bool anyNonSpecularBounces, int pixelIndex)
    {
        int index = AllocateEntry();
        DCHECK(!ray.HasNaN());
        ref RayWorkItem w = ref this[index];
        w.ray = ray;
        w.depth = depth;
        w.pixelIndex = pixelIndex;
        w.prevIntrCtx = prevIntrCtx;
        w.beta = beta;
        w.r_u = r_u;
        w.r_l = r_l;
        w.lambda = lambda;
        w.anyNonSpecularBounces = anyNonSpecularBounces;
        w.specularBounce = specularBounce;
        w.etaScale = etaScale;
        return index;
    }
}

// ShadowRayQueue Definition
public sealed class ShadowRayQueue(int n) : WorkQueue<ShadowRayWorkItem>(n);

// EscapedRayQueue Definition
public sealed class EscapedRayQueue(int n) : WorkQueue<EscapedRayWorkItem>(n)
{
    // EscapedRayQueue Public Methods
    public int Push(in RayWorkItem r) =>
        Push(new EscapedRayWorkItem
        {
            rayo = r.ray.o, rayd = r.ray.d, depth = r.depth, lambda = r.lambda, pixelIndex = r.pixelIndex,
            beta = r.beta, specularBounce = r.specularBounce, r_u = r.r_u, r_l = r.r_l, prevIntrCtx = r.prevIntrCtx
        });
}

