// SubsurfaceScatterQueue Definition
public sealed class SubsurfaceScatterQueue(int n) : WorkQueue<SubsurfaceScatterWorkItem>(n);

// MediumSampleQueue Definition
public sealed class MediumSampleQueue(int n) : WorkQueue<MediumSampleWorkItem>(n)
{
    // (pbrt doesn't set _depth_ here, so the item has whatever depth was
    // left in its slot of the queue.)
    public int Push(in RayWorkItem r, Float tMax) =>
        Push(new MediumSampleWorkItem
        {
            ray = r.ray, depth = r.depth, tMax = tMax, lambda = r.lambda, beta = r.beta, r_u = r.r_u, r_l = r.r_l,
            pixelIndex = r.pixelIndex, prevIntrCtx = r.prevIntrCtx, specularBounce = r.specularBounce,
            anyNonSpecularBounces = r.anyNonSpecularBounces, etaScale = r.etaScale
        });
}

// MediumScatterQueue Definition
public sealed class MediumScatterQueue(int n) : WorkQueue<MediumScatterWorkItem>(n);

// MaterialEvalQueue Definition
public sealed class MaterialEvalQueue(int n) : WorkQueue<MaterialEvalWorkItem>(n);
